def fuzzy_search_A(docs, query, threshold=0.7):
    import difflib
    out = []
    for doc_id, text in docs.items():
        ratio = difflib.SequenceMatcher(None, query.lower(), text.lower()).ratio()
        if ratio >= threshold:
            out.append((doc_id, ratio))
    return sorted(out, key=lambda x: -x[1])
```

