```python
import difflib

class HybridSearch:
    def __init__(self, docs, fuzzy_threshold=0.7):
        self.docs = docs
        self.index = {}
        for doc_id, text in docs.items():
            for tok in text.lower().split():
                self.index.setdefault(tok, set()).add(doc_id)
        self.threshold = fuzzy_threshold

    def search(self, query):
        q = query.lower()
        # 1) Exact hits via inverted index (B's fast path)
        hits = set(self.index.get(q, set()))
        if hits:
            return sorted(hits)
        # 2) Fuzzy fallback: find index tokens similar to query, union their doc sets
        candidates = set()
        for tok in self.index:
            if difflib.SequenceMatcher(None, q, tok).ratio() >= self.threshold:
                candidates.update(self.index[tok])
        # Rank candidates by best fuzzy ratio of any token in the doc against query
        ranked = []
        for doc_id in candidates:
            text = self.docs[doc_id].lower()
            best = max(
                difflib.SequenceMatcher(None, q, tok).ratio()
                for tok in text.split()
            )
            ranked.append((doc_id, best))
        return [d for d, _ in sorted(ranked, key=lambda x: -x[1])]
```

The synthesis adopts B's inverted-index (fast exact lookup) as the primary path, and falls back to A's fuzzy-matching ONLY over index tokens (not over full document texts) — reducing A's O(n*m) cost to O(|vocab|*m) with typically much smaller |vocab|. Exact queries pay B's cost; typo queries pay A's cost scoped to the vocabulary.

