import time, uuid, requests

def request(method, url, json_body=None, retries=3, timeout=10):
    headers = {}
    if method.upper() == 'POST':
        headers['Idempotency-Key'] = str(uuid.uuid4())  # From B
    for i in range(retries):
        try:
            r = requests.request(
                method=method.upper(),
                url=url,
                json=json_body,
                headers=headers,
                timeout=timeout,  # From A
            )
            if r.status_code < 500:
                return r
        except requests.RequestException:
            pass
        time.sleep(2 ** i)  # From A
    raise RuntimeError('max retries exceeded')
```

The key is that the idempotency key is generated ONCE per call and reused across retries — otherwise retries with fresh keys would duplicate state on a server that replied 500 after already committing.

