```python
from collections import OrderedDict
import math, mmh3

class HybridDedup:
    def __init__(self, expected_n=10_000_000, fpr=0.001, exact_cache_size=100_000):
        self.size = int(-(expected_n * math.log(fpr)) / (math.log(2) ** 2))
        self.num_hashes = int((self.size / expected_n) * math.log(2))
        self.bits = bytearray(self.size // 8)
        self.exact = OrderedDict()  # LRU for Bloom-hit confirmations
        self.exact_cap = exact_cache_size

    def _bloom_has(self, x):
        return all(
            (self.bits[h // 8] >> (h % 8)) & 1
            for h in (mmh3.hash(str(x), i) % self.size for i in range(self.num_hashes))
        )

    def _bloom_add(self, x):
        for i in range(self.num_hashes):
            h = mmh3.hash(str(x), i) % self.size
            self.bits[h // 8] |= (1 << (h % 8))

    def seen(self, x):
        # Fast path: Bloom says no -> definitely new
        if not self._bloom_has(x):
            self._bloom_add(x)
            if x in self.exact:
                self.exact.move_to_end(x)
            else:
                self.exact[x] = True
                if len(self.exact) > self.exact_cap:
                    self.exact.popitem(last=False)
            return False
        # Bloom says maybe -> check exact
        if x in self.exact:
            self.exact.move_to_end(x)
            return True
        # Bloom-hit but not in exact cache: treat as unseen but add (best-effort).
        # This preserves the 'drop NO unique items' invariant: ambiguous cases are treated as new.
        self._bloom_add(x)
        self.exact[x] = True
        if len(self.exact) > self.exact_cap:
            self.exact.popitem(last=False)
        return False

def dedup(items):
    d = HybridDedup()
    for x in items:
        if not d.seen(x):
            yield x
```

The synthesis preserves B's memory bound (Bloom filter fixed size + a small bounded exact cache) AND A's zero-false-negative guarantee. Trade-off: on Bloom-hits that are NOT in the exact cache, we conservatively assume 'new' — this slightly weakens dedup accuracy (may yield duplicates) but NEVER drops unique items, which matches the target's strict constraint.

